insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 1, 'One ref-540-2500 stage makes 28 ft of head at 2500 bbl/d. What changes when several hundred of that same stage are put on one shaft?', '["Both head and rate, because the stages act in series on the fluid and each one adds its share of the flow it receives.", "The rate, because the stack passes the fluid through many impellers in series.", "Only the head, because head is bought by stacking while the rate a stage passes is fixed by the stage.", "The head and the peak efficiency, since a taller stack runs nearer its best efficiency point."]'::jsonb, 2, 'A well wanting thousands of feet of lift needs more of the same stage rather than a different one.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 2, 'Across the four reference stages in the catalogue, how do rate at best efficiency, head at best efficiency and peak efficiency move together?', '["A wider housing passes more rate and makes less head for it, while peak efficiency runs the other way and rises from 0.63 to 0.74.", "All three rise together with housing outside diameter.", "Rate rises with housing outside diameter while head and peak efficiency both fall, because a larger impeller loses more energy to recirculation at the eye.", "Head rises with housing outside diameter while rate and peak efficiency both fall away from the smallest stage in the catalogue."]'::jsonb, 0, 'The catalogue runs from 4.00 in housing at 1000 bbl/d and 33 ft to 6.75 in at 7000 bbl/d and 18 ft.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 3, 'What is a catalogue reference stage such as ref-540-2500 in this package?', '["A digitised manufacturer curve.", "A shape built from four named parameters, a rate and a head at best efficiency, a shutoff to best efficiency head ratio and a peak efficiency, with no manufacturer behind it.", "A published pump model whose part number can be quoted on a purchase order.", "An average of several vendor sheets in the 540 series, blended so that a design can proceed before a specific pump is chosen."]'::jsonb, 1, 'It carries a housing outside diameter of 5.13 in and nothing else a purchase order could use.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 4, 'The shipped cable table carries copper resistance and no ampacity column. What is the honest statement about the cable check that runs on it?', '["The check fails safe, so any cable it approves is confirmed to carry the current at well temperature and can be taken as sized.", "The check is wrong and the cable it picks will always be undersized for the current the motor draws down the string.", "The check is unreachable, so the table never returns a cable size at all.", "The check does not currently check anything, since it is true by construction, which is not the same as saying the cable is wrong."]'::jsonb, 3, 'Ampacity belongs to the insulation system and the well temperature, which makes it an input rather than a property of copper.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 5, 'What does this module actually hold as a stage curve?', '["A head fit and an efficiency fit in rate, taken at a reference frequency of 60 Hz on a curve fluid of specific gravity 1.0.", "A measured curve at each of the standard drive frequencies, with the reading interpolated between the two frequencies nearest the duty.", "A geometric model of the impeller and diffuser from which head and efficiency are computed at any speed.", "A lookup table of head against rate at several fluid gravities, bracketed and interpolated on both axes at reading time."]'::jsonb, 0, 'Everything off the reference frequency is derived from that one curve by the affinity laws.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 6, 'A duty of 1800 bbl/d is asked for at 40 Hz, where the speed ratio is 0.66666667. At what rate does the engine read the reference curve?', '["1800.000000 bbl/d, because the affinity mapping is applied to head and to power but never to the rate the reading is taken at.", "1200.000000 bbl/d, because the duty rate is multiplied by the speed ratio to bring it onto the reference curve before head is read off it.", "2700.000000 bbl/d.", "2700.000000 bbl/d only when the pumped fluid is the curve fluid, and the duty rate itself on any other gravity."]'::jsonb, 2, 'The mapping is worked backwards first, so head at that equivalent rate is then scaled forward by the square of the ratio.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 7, 'The same 1800 bbl/d duty returns an efficiency of 0.6391314286 at 60 Hz and 0.7385257143 at 40 Hz, yet the affinity law says efficiency does not move with speed. Why is there no contradiction?', '["Efficiency is corrected for the change in Reynolds number at the lower shaft speed, which the module applies on top of the affinity mapping.", "The law holds at a fixed point on the reference curve, and slowing the drive moved the point from 1800 bbl/d to 2700.000000 bbl/d.", "The efficiency fit is rebuilt at each drive frequency.", "The law applies only above the best efficiency rate, so a reading below it is scaled by the ratio of the two speeds instead."]'::jsonb, 1, 'Head at those two readings is 31.2742857143 ft and 11.7853968254 ft on the same published golden case.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 8, 'What does `stagePerformance` return when it is called at zero frequency?', '["Head zero with a region of `downthrust`, since no rotation means no head and the duty sits below every published rate on the curve.", "The 60 Hz reading unchanged, on the grounds that the speed ratio is undefined and the reference curve is the only curve there is.", "An error object that stops the calculation.", "Head NaN, a region of `invalid` and inside the published range false, which is the reading declaring that it failed."]'::jsonb, 3, 'That is one of the very few places in this module where the reading itself reports a failure rather than handing back a number.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 9, 'Given only two points from a vendor curve, what does `fitStageCurve` do?', '["It fits a straight line through the two points and flags the reading as weak, so the design can proceed while the missing points are chased.", "It accepts them and raises a warning that the residual cannot be evaluated on so few points, leaving the head fit in place for reading.", "It returns ok false with a message asking for at least three points, and no head fit at all.", "It falls back to the nearest reference stage of the same housing series."]'::jsonb, 2, 'Nothing downstream can read a curve that does not exist, so this failure stops where it started.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 10, 'A curve is supplied with head points but no efficiency points. What comes back?', '["Ok true with a warning, a working head fit still reading 27.914286 ft at 2500 bbl/d, and NaN for the best efficiency rate and the brake power per stage.", "Ok false, since a stage is defined by three curves and one of them is missing.", "Ok true with every reading intact, because efficiency is recovered from the head fit and the pumped gravity by the brake power relation.", "Ok true with a default peak efficiency taken from the nearest reference stage in the catalogue, so that power per stage still has a value."]'::jsonb, 0, 'A curve missing half its data is accepted with two holes in it, and the holes appear only in the fields that use them.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 11, 'At 20 cp on a 58 lbm/ft3 fluid the kinematic viscosity is 21.517241 cSt, above the 10 cSt mark. What does the module do with the head and efficiency?', '["It applies a Hydraulic Institute head and efficiency correction from the chart and records the factors it used against the reading.", "It refuses the reading entirely and returns NaN for head, so that no stage count can be built on an uncorrected viscous duty.", "It scales head and efficiency by the ratio of the viscosity to the 10 cSt threshold.", "It reports that a correction is required, applies none, and hands back the water curve unchanged."]'::jsonb, 3, 'The chart is ANSI/HI 9.6.7 and it is not reproduced from memory, because invented factors would be worse than none.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 12, 'The published golden vendor curve carries a published range of 1500 to 3500 bbl/d. What does that range state?', '["The rates at which the pump can mechanically be run without thrust damage to the stages, taken from the manufacturer''s own operating limits.", "Where the vendor measured, which is the two end rates and nothing more.", "Where the stage may be operated, since the polynomial has no value outside it.", "The band within which the stage stays inside a quarter of its best efficiency rate, which is the recommended range the vendor advises for continuous duty."]'::jsonb, 1, 'The curve still answers outside that range, which is what makes the range a statement about provenance rather than about capability.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 13, 'Under the affinity laws as this module applies them, what happens to rate, head, power and efficiency when the drive speed changes?', '["Rate scales with speed, head with speed squared, power with speed cubed, and efficiency does not move at all.", "Rate scales with speed squared, head with speed cubed and power with the fourth power of speed, while efficiency scales with speed directly.", "All four scale with speed directly, since one shaft turns them all.", "Rate and head both scale with speed, power with speed squared, and efficiency falls with the square of the speed ratio away from the reference."]'::jsonb, 0, 'Those exponents are exact for a fixed impeller, and this module carries no trim, no wear factor and no stage by stage variation.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 14, 'Head, efficiency and brake power per stage are read at 2500 bbl/d on a specific gravity of 1.00 and again on 0.90. Which readings move?', '["Head and brake power, since a lighter fluid is lifted further by the same energy input while the shaft power falls in proportion to it.", "All three, because the fit was measured on the curve fluid and every reading off it is scaled by the ratio of the pumped gravity to that fluid.", "Brake power alone, from 0.69851755 hp to 0.62866580 hp.", "None, because gravity enters only when the stage count is multiplied out to a total dynamic head for the whole stack."]'::jsonb, 2, 'Head stays at 27.914286 ft and efficiency at 0.73657143 fraction down both fluids, because gravity enters the power statement and nothing else.'),
  ('esp', 'beginner', 'module', 'm01-a-stack-of-stages', 15, 'Brake power per stage on a specific gravity of 1.00 climbs from 0.64381596 hp at 1500 bbl/d to 0.75437842 hp at 3500 bbl/d without turning over. What follows for a motor?', '["Nothing, since power per stage is multiplied by the stage count and the stack rounds up.", "A stage at its best efficiency is not a stage drawing its least power, so a motor sized at the best efficiency rate can be undersized at the top of the range.", "The motor should be sized at the lowest rate on the published curve, where the head is tallest and the shaft therefore carries its heaviest load.", "Power turns over above the published range, so the motor is sized at the high end of the data and carries its own margin against extrapolation."]'::jsonb, 1, 'Rate rises faster than head and efficiency fall, so the product keeps growing even after efficiency has fallen to 0.64942857 fraction.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 1, 'What does `fitStageCurve` build from the five points read off a manufacturer published curve?', '["A cubic spline through all five points.", "A least squares cubic in rate for head and another for efficiency, so four coefficients are asked to pass through five points.", "A cubic passing exactly through the two end points and the peak, with the other two points left to check the residual.", "A quadratic in rate for head and a cubic for efficiency, since a published head curve is known to be parabolic."]'::jsonb, 1, 'Brake power fit present is false on that curve, so a stage has two fitted curves and one derived one.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 2, 'Why does the vendor head fit miss every one of the five published points?', '["The points are rounded to four decimal places on the manufacturer sheet before they are typed in, and the fit inherits that rounding at each rate.", "The fit is built in a normalised variable rather than in rate, and converting back leaves a small error at every point.", "The head points were measured at 60 Hz and the fit reads at the duty frequency.", "Four coefficients cannot pass through five points, so a least squares cubic distributes the miss rather than eliminating it."]'::jsonb, 3, 'The response is not to force the fit through the points, since a quartic through five points would have no residual and would swing violently between them.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 3, 'The head residuals on the published golden vendor curve run -0.01428571, 0.05714286, -0.08571429, 0.05714286 and -0.01428571 ft. What does that pattern show?', '["A least squares fit behaving normally, since the signs alternate and the magnitudes are symmetric about the middle point.", "A transcription error at 2500 bbl/d, since the largest miss falls on that rate.", "A fit of too low a degree for the curvature, which a quartic would remove by following the points closely.", "A scaling error in the normalising variable."]'::jsonb, 0, 'The largest miss, at 2500 bbl/d, is nothing per stage and is real head once it is carried into a stack of a few hundred stages.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 4, 'A set of head residuals comes back neither alternating in sign nor symmetric in magnitude. What does that usually mean?', '["The published range is too wide for a single fit, so the curve should be split at the best efficiency rate and fitted in two pieces.", "The degree of the fit is too high for the number of points supplied, and the curve is swinging between them instead of passing smoothly through.", "One point is wrong rather than the fit being poor.", "The fit was built on unnormalised rates, which puts columns spanning several orders of magnitude into the same normal equations."]'::jsonb, 2, 'That is why the residual at each point is the check that works, while an aggregate over all of them is not.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 5, 'The head fit rmse on ref-400-1000 is 0.00000000000018 ft. What does that number tell you about the stage?', '["That the reference stage is the best characterised stage in the catalogue.", "Nothing about any pump, because the nine points were generated from a quadratic shape and then fitted with a quadratic.", "That the reference curve was fitted at a higher degree than the vendor curve was, which is why its residual is so many orders of magnitude smaller.", "That the generating parameters came from a manufacturer sheet with more points than the vendor curve."]'::jsonb, 1, 'The residual there is machine noise rather than evidence, and the number that means something is the vendor curve''s.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 6, 'Why is quoting ref-540-2500 as a real pump a provenance error rather than a rounding one?', '["It is a labelled reference shape with four named parameters and a housing outside diameter of 5.13 in, and no manufacturer part number sits behind it.", "Its head at best efficiency is quoted to eight decimal places, which no vendor sheet supports.", "Its published range of 1250 to 3500 bbl/d is wider than any real 540 series pump would be sold with, so any duty inside it is unsupported.", "Its curve was fitted at degree 2 rather than degree 3, which is a lower order than a manufacturer curve is normally read at."]'::jsonb, 0, 'A reference stage is a shape fitted to itself, so its own residual could never have been anything other than machine noise.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 7, 'The vendor head fit is built in z, the rate divided by a normalising scale of 3500 bbl/d. What does the coefficient of -29.7499999999 on z squared mean?', '["A head per squared bbl/d, which is why it is larger than the coefficient on the cubic term.", "A head in ft at the top of the published range, since z is one there and the term reduces to the coefficient itself at that rate.", "A head per squared fraction of 3500 bbl/d, which is wrong by the square of the scale if it is quoted any other way.", "A head per bbl/d."]'::jsonb, 2, 'Working in z keeps every column of the normal equations near one, instead of cubing raw rates in the thousands.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 8, 'The cubic coefficient of the vendor head fit comes back as -0.0000000001 ft. What does that say about the published head points?', '["They are too few for a cubic to be identified at all, so the solver has set the highest coefficient to zero and returned a quadratic in its place.", "They are badly conditioned in the normalising variable, which drives the highest coefficient toward zero and makes the whole fit unreliable.", "They sit on a straight line, since a vanishing cubic term leaves only a linear fit.", "They describe a parabola, so the head cubic is buying a term that is numerically zero."]'::jsonb, 3, 'The efficiency fit does not behave that way, carrying 0.571666666703 fraction on the same power, which is why that curve is not symmetric about its peak.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 9, 'What exactly does the fit check on the golden vendor curve compare, and against what?', '["The largest single head residual against two percent of the head at the best efficiency rate.", "The head fit rmse against two percent of the tallest published head point, which is 0.6400 ft on a curve topping out at 32.0000 ft.", "The head fit rmse and the efficiency fit rmse together against two percent of the tallest published head point and of the peak efficiency in turn.", "The head read at each published rate against the published head there, so that any point missed by more than two percent raises its own warning."]'::jsonb, 1, 'The rmse is 0.0534522484 ft on that curve, or 0.00167038 of the threshold, and warnings raised is 0.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 10, 'On the teaching curve BRASS-11, one head point is typed as 26.0 where the sheet says 28.0. What does the check do?', '["Nothing, because the rmse rises from 0.05345225 to 0.58797473 ft and that still sits below the 0.640000 ft threshold.", "It raises one warning, since a tenfold degradation in the rmse trips a relative test of its own.", "It raises one warning naming the rate at which the point was mistyped, which is how a mild transcription error is meant to be caught.", "It rejects the curve and returns ok false, on the grounds that a head point out by two full feet cannot be a transcription the fit should accept."]'::jsonb, 0, 'BRASS-11 is a teaching curve rather than a published case, and its mild version still answers at every rate and still looks like a pump curve.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 11, 'Why does an rmse under its threshold fail to catch a single mistyped head point?', '["Because the rmse is computed after the fit has already absorbed the bad point, so the residual it would have left behind has been removed by the least squares solve.", "Because the threshold is set from the tallest published head point, which rises when a point is mistyped upward and lifts the bar with it.", "Because the rmse is taken on the efficiency fit rather than the head fit, and the efficiency points were not the ones mistranscribed.", "An aggregate averages one large residual away among four small ones."]'::jsonb, 3, 'The check that works is the residual at each point, and the decimal slip version is caught only because its rmse of 5.92250912 ft is many times the bar.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 12, 'A head point on the golden vendor curve is mistyped and the best efficiency rate still comes back 2635.0000 bbl/d. Why?', '["The scan is quantised to 5.0000 bbl/d, so a shift caused by a head error of about one foot is smaller than one step of the grid it lands on.", "The rate is taken from the tallest published head point, which is unchanged when a point in the middle of the curve is mistyped downward.", "The best efficiency search reads the efficiency fit alone, and the efficiency points were not touched.", "The best efficiency rate is recomputed from the nearest reference stage instead."]'::jsonb, 2, 'The head reported at that rate does move, from 26.992525 ft to 26.041925 ft on the mild teaching version, and there is no check at all on the efficiency transcription.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 13, 'How is head at a rate obtained once the fit exists?', '["By interpolating between the two published points that bracket the rate.", "By evaluating the polynomial at that value of z, with no interpolation between vendor points and no lookup table.", "By bracketing the rate between two published points and blending the fit against the published heads at each end, so the reading honours the sheet.", "By reading the nearest published point and correcting it with the local slope of the fit."]'::jsonb, 1, 'Whatever the cubic got wrong at the published points, it gets wrong between them too, which is why fit quality is the whole story.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 14, 'A duty of 2500 bbl/d is read at 50 Hz and returns 16.7063492063 ft, where the same duty at 60 Hz returns 27.9142857143 ft. What is the tell that the affinity mapping has happened?', '["The head has fallen by more than a third, which no fitted curve can do over a rate interval as short as the one between those two readings.", "The reading carries a warning that the drive frequency is below the reference frequency the published points were measured at.", "The equivalent rate is 3000.000000 bbl/d rather than 2500 bbl/d.", "The efficiency is unchanged between the two readings, since the affinity law holds efficiency fixed while head is scaled by the square of the ratio."]'::jsonb, 2, 'A reference rate equal to the duty rate means either that the drive is at 60 Hz or that something is wrong.'),
  ('esp', 'beginner', 'module', 'm02-fitting-a-curve', 15, 'Viscosity correction factors of 0.85 on head and 0.70 on efficiency are supplied for a duty reading 28.00000000 ft and 0.7000000000 fraction uncorrected. What comes back?', '["23.80000000 ft and 0.4900000000 fraction, because supplied factors are applied as straight multipliers on the two readings.", "23.80000000 ft and 0.7000000000 fraction, since only the head factor is applied.", "28.00000000 ft and 0.7000000000 fraction, since factors are reported and not applied.", "The water curve readings with a note that a correction is required and no factors applied."]'::jsonb, 0, 'Supply nothing and the reading comes back unchanged, which is the difference between a factor being required and a factor being entered.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 1, 'The best efficiency point of a stage is the maximum of which curve?', '["The head fit, since the point of a pump is head.", "The efficiency fit alone, with the head and the power reported beside it being readings at that rate rather than optima of their own.", "The brake power fit, taken at its minimum.", "All three fits together, at the rate where the head, the efficiency and the brake power curves are each closest to their own best values."]'::jsonb, 1, 'Efficiency is the only one of the three readings with an interior maximum inside the published range, which is why the operating band is built around it.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 2, 'What best efficiency point does the published golden vendor curve return?', '["A rate of 2500 bbl/d, an efficiency of 0.74 fraction and a head of 28.0000 ft, which are the values printed on the manufacturer sheet itself.", "A rate of 2750 bbl/d, an efficiency of 0.73737500 fraction and a head of 26.137500 ft, which is the highest efficiency of the nine tabulated readings.", "A rate of 2635.0000 bbl/d, an efficiency of 0.73657143 fraction and a head of 31.985714 ft, pairing the peak rate with the tallest head on the curve.", "A rate of 2635.0000 bbl/d, an efficiency of 0.739054805 fraction and a head of 26.992525 ft."]'::jsonb, 3, 'All three of those values are recorded in the golden itself.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 3, 'How does the head at the best efficiency rate compare with the head elsewhere on the published golden vendor curve?', '["It is one of the lower heads the stage makes, since head falls monotonically and reaches 31.985714 ft at 1500 bbl/d.", "It is the tallest head on the curve, which is what the best efficiency rate is chosen to deliver.", "It is the head at which the curve is flattest, so a small error in the duty rate costs less head there than anywhere else in the published range.", "It is the midpoint of the head range, since the efficiency peak sits at the centre of the published rates."]'::jsonb, 0, 'The best efficiency head is 26.992525 ft, and quoting it as the pump''s head is the second of the two errors this reading invites.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 4, 'Brake power per stage on a specific gravity of 1.00 runs 0.64381596 hp at 1500 bbl/d and 0.75437842 hp at 3500 bbl/d. Where does the minimum power sit?', '["At the best efficiency rate, because the least energy is wasted there and the shaft therefore carries its lightest load on the whole curve.", "At the top of the published range, where efficiency has fallen back.", "At the bottom of the published range, since power climbs the whole way and never turns over.", "Between the best efficiency rate and the top of the range, where the falling head has begun to outrun the rising rate in the power product."]'::jsonb, 2, 'A motor sized on the assumption that best efficiency means least power comes up short.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 5, 'The manufacturer sheet reports 74.00 percent at 2500 bbl/d and the engine reports 0.739054805 fraction at 2635.0000 bbl/d. Why are those not the same claim?', '["The sheet quotes efficiency as a percentage while the engine quotes a fraction, so the two figures differ only by the scale they are expressed on.", "The first is a measured point and the second is the peak of a cubic fitted through five of them, and that cubic reads 0.73657143 fraction at 2500 bbl/d.", "The engine reports its peak at the pumped gravity while the sheet reports its own at the curve fluid, and gravity moves the efficiency reading.", "The engine reports at the duty frequency while the sheet was measured at 60 Hz."]'::jsonb, 1, 'The difference between 2500 and 2635.0000 bbl/d is not rounding.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 6, 'How does `bepOf` locate the best efficiency point?', '["It scans the efficiency fit across the published range in 400 equal steps and keeps the largest value it sees.", "It differentiates the efficiency cubic and solves for the stationary point, then checks the second derivative to confirm it is a maximum.", "It brackets the peak between the two highest published efficiency points and refines the bracket until the rate converges to a set tolerance.", "It takes the published point with the highest efficiency on the manufacturer sheet."]'::jsonb, 0, 'There is no derivative, no bracket and no convergence test anywhere in that search.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 7, 'The published range of the golden vendor curve is 1500 to 3500 bbl/d. What is the spacing of the grid the best efficiency rate lands on?', '["1.0000 bbl/d, since the scan refines its step until the rate it returns is resolved to a barrel per day.", "500 bbl/d, since the scan visits the five published points and reports whichever of them carries the highest fitted efficiency.", "It varies with the curvature of the efficiency fit, since the scan takes finer steps as it approaches the peak it is closing in on.", "5.0000 bbl/d."]'::jsonb, 3, 'That spacing is the range divided by 400, so a wide published range gets a coarse grid and a narrow one a fine grid whatever the shape of the curve.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 8, 'Reference stage ref-540-2500 was generated with its best efficiency point at 2500 bbl/d, and `bepOf` returns 2498.7500 bbl/d for it. What does that gap show?', '["The generating parameters and the fitted curve disagree, because the quadratic fit through the nine generated points does not recover the shape exactly.", "The published range of that stage is too narrow, so the peak sits outside the search interval.", "The grid does not contain the true peak, so the scan returns the nearest step to it rather than the peak itself.", "The efficiency fit has been built on the pumped gravity rather than the curve fluid, which shifts the peak away from the generating rate."]'::jsonb, 2, 'All four reference stages miss in the same way, coming back at 1001.1250, 2498.7500, 4002.0000 and 7001.5000 bbl/d against generating rates of 1000, 2500, 4000 and 7000 bbl/d.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 9, 'Why is it wrong to describe 2635.0000 bbl/d as the rate at which the best efficiency point was found?', '["Found implies a solve, which implies a residual and a tolerance, and none of that exists in a scan across a fixed grid.", "Because the rate is quoted to four decimal places while the published range is quoted to none.", "Because the efficiency at that rate was never measured by the vendor, so no rate on a fitted curve can be described as found at all.", "Because the search reads the efficiency fit rather than the head fit."]'::jsonb, 0, 'Treating that rate as the peak resolved to a barrel per day claims a resolution the scan does not have.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 10, 'The scan keeps a value only when it is strictly larger than the best so far. What does that do to a flat efficiency peak?', '["It resolves to the highest rate on the flat, since the scan walks upward and the last equal value it meets replaces the one before it.", "It resolves to the lowest rate on the flat, because the tie is broken toward the low side.", "It returns NaN, because a flat peak gives the search no single largest value to keep and the result would otherwise be arbitrary.", "It resolves to the midpoint of the flat, which is the convention the search uses when several grid points return the same efficiency."]'::jsonb, 1, 'That behaviour matters most on a curve whose efficiency fit is nearly symmetric near its top.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 11, 'Sweeping the golden vendor efficiency by hand at 250 bbl/d intervals gives a highest sample of 0.73737500 fraction at 2750 bbl/d. What has that sweep got wrong?', '["Nothing, since 2750 bbl/d is the rate a 400 step scan across the published range would also land on with that efficiency.", "It read the published efficiency points rather than the fit, so the sample it kept is a measured value and not a value off the cubic curve.", "It names a rate 115 bbl/d above the peak, because a coarse spacing stepped over the higher value the finer grid finds.", "It swept the head fit instead of the efficiency fit, which peaks at a different rate because head falls monotonically across the range."]'::jsonb, 2, 'The scan returns 0.739054805 fraction at 2635.0000 bbl/d, above both the hand sample and the 0.73657143 fraction the fit reads at 2500 bbl/d.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 12, 'The `region` field is computed by two different rules. What are they?', '["Inside the published range the band decides, and outside it the reading is `invalid`.", "The band decides at the reference frequency and the published range decides at every other drive frequency the duty is read at.", "The band decides for head readings and the published range for efficiency readings.", "Inside the published range a band of 0.75 to 1.25 around the scanned best efficiency rate decides, and outside it the published range alone decides."]'::jsonb, 3, 'The field returns the same string for both rules, so the word alone does not say which one produced it.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 13, 'Reference stage ref-540-2500 returns `upthrust` at 3350 bbl/d and `upthrust` again at 3800 bbl/d. What separates the two readings?', '["Inside the published range is true at 3350 bbl/d and false at 3800 bbl/d, so one word came off measured data and the other off a polynomial.", "Nothing beyond the rate, since both sit above the recommended band and carry the same evidence behind the word.", "The 3800 bbl/d reading carries a warning that the duty is outside the published range, which the 3350 bbl/d reading does not carry.", "The 3350 bbl/d reading was decided by the published range and the 3800 bbl/d reading by the band around the best efficiency rate."]'::jsonb, 0, 'That stage runs 1250.00 to 3500.00 bbl/d with a recommended band of 1874.0625 to 3123.4375 bbl/d, and the head of 15.15808000 ft at 3800 bbl/d came from a fit evaluated where nothing was measured.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 14, 'Why is acting on `region` without reading `inRange` beside it a mistake?', '["Because `region` is only populated when the duty is inside the published range.", "An in-range `upthrust` is an operating decision on measured data, while an out-of-range one is a data problem carrying a number off a fit that has left its data.", "Because `region` is computed before the affinity mapping is applied, so it describes the reference rate rather than the duty rate that was asked about.", "Because `region` is taken from the catalogue entry for the stage rather than from the reading, so it says nothing about the duty at all."]'::jsonb, 1, 'Only `recommended` carries a guarantee of provenance, because it is never awarded outside the published range.'),
  ('esp', 'beginner', 'module', 'm03-the-best-efficiency-point', 15, 'Of everything reported at the peak efficiency rate, which statement is the one the scan actually guarantees?', '["That the head of 26.992525 ft reported with it matches the manufacturer sheet.", "That the stage is running within the recommended band at that rate, whatever the duty rate turns out to be once the drive frequency is set.", "That 0.739054805 fraction is the largest value the efficiency fit takes anywhere on the grid it was scanned across.", "That the transcription behind it is sound, because a mistyped point would have moved the rate the scan returns and shown up as a warning."]'::jsonb, 2, 'A mild head transcription error moves the reported best efficiency head from 26.992525 to 26.041925 ft on the teaching curve BRASS-11 while leaving the rate at 2635.0000 bbl/d.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 1, 'Swept across the drive at a fixed duty of 2500 bbl/d, the stage makes 7.10873016 ft at 40 Hz and 40.73253968 ft at 70 Hz. What does it make at 50 Hz?', '["27.9142857143 ft, unchanged.", "31.985714 ft, the tallest head on the curve.", "16.70634921 ft, read off an equivalent rate of 3000.000000 bbl/d on the 60 Hz curve and then scaled forward.", "18.98571429 ft, the head at the top of the data."]'::jsonb, 2, 'The engine holds one curve at 60 Hz and no curve per frequency, so every duty off the reference speed is answered by mapping back, reading, and mapping forward.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 2, 'At a fixed 2500 bbl/d the 50 Hz head is 0.59848743 of the 60 Hz head, while the speed ratio squared is 0.69444444. What accounts for the difference?', '["Holding the duty rate fixed moves the reading to a different place on the reference curve, so the curve shape acts alongside the affinity law.", "The affinity law for head is only an approximation, and it loses accuracy whenever the drive is taken below the reference frequency the vendor measured the published curve at.", "The head fit leaves a residual of 0.0534522484 ft against a transcription threshold of 0.640000 ft, and that fitting error is what separates the observed multiple from the theoretical one.", "The pumped gravity of 0.90 scales the head."]'::jsonb, 0, 'The square law is exact when the reference rate moves with the speed, which is what happens when a whole curve is scaled rather than one duty held.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 3, 'The same 2500 bbl/d duty is asked for efficiency rather than head, with the drive at 50 Hz. What comes back?', '["0.73657143 fraction, the 60 Hz value at 2500 bbl/d, since efficiency is the one reading the affinity laws leave alone and the duty rate is therefore read directly on the published curve.", "0.739054805 fraction, the peak of the efficiency fit.", "0.64942857 fraction, scaled down by the speed ratio.", "0.7222857143 fraction, exactly what the 60 Hz curve reads at 3000.000000 bbl/d, because efficiency does not scale with speed."]'::jsonb, 3, 'Efficiency not scaling with speed is not the same thing as efficiency being read at the duty rate, and the second is the error the first invites.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 4, 'Which published efficiency point does the cubic efficiency fit miss by the largest residual?', '["55.00 percent at 1500 bbl/d, where the fit reads 0.54942857 fraction and the measured curve is still climbing steeply towards its peak.", "74.00 percent at 2500 bbl/d.", "65.00 percent at 3500 bbl/d, the last measured point, where a least squares fit is least constrained by neighbouring points on either side.", "68.00 percent at 2000 bbl/d, which sits on the steepest part of the rise and is therefore the hardest point for a smooth curve to hold."]'::jsonb, 1, 'Its residual is -0.00342857 fraction, and the residuals alternate in sign and run symmetrically about that middle point.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 5, 'A report quotes 0.739054805 fraction as the efficiency at a duty of 2500 bbl/d. What does that do to the shaft work?', '["It understates the brake power at every stage in the stack, because efficiency divides and the duty reading is the lower 0.73657143 fraction.", "It overstates the brake power at every stage, because the peak sits at 2635.0000 bbl/d and a higher rate always carries a higher hydraulic power through the same divisor.", "It leaves the brake power untouched and moves only the region word, since the peak value grades the duty against the recommended band rather than entering the power statement.", "It has no effect, since the two values differ inside rounding."]'::jsonb, 0, 'The peak is the largest value the efficiency fit takes anywhere on the grid it was scanned across, so quoting it at any other rate can only flatter the design.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 6, 'The published golden vendor curve records that a brake power fit is not present. Where does horsepower per stage come from?', '["It is interpolated between published power points.", "It is looked up against the motor nameplate.", "It is built out of the head reading, the efficiency reading, the rate and the pumped gravity through the divisor 135635.80083124.", "It comes off the head fit, efficiency being dimensionless."]'::jsonb, 2, 'That is why a stage carries two fitted curves and one derived one, and why a missing efficiency shows up in the power and nowhere else.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 7, 'This package''s exact divisor carried into pressure units is 58775.513694, against the familiar rounded 58824. How far apart are the two?', '["0.076982 percent, the same gap the module carries between its two conversions for one gradient.", "0.0008242606 in relative terms.", "0.0021380899 fraction, which is the residual the efficiency fit leaves against the five published points.", "0.00167038 of the threshold, the proportion the head fit residual bears to two percent of the tallest point."]'::jsonb, 1, 'The rounded form is a field convention rather than a different physical statement, and nothing in the package actually computes with 58824.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 8, 'A horsepower is quoted off a curve sheet with no record of which fluid the sheet was drawn for. How large is that error at 1500 bbl/d?', '["Large enough to be caught by eye, because the head reading moves from 31.985714 ft to a visibly different value once the lighter fluid is applied to the same published point.", "It cancels once the stage count is applied.", "None, since a sheet is drawn on the pumped fluid.", "About a tenth of the number, 0.64381596 hp on water against 0.57943436 hp on a 0.90 gravity fluid."]'::jsonb, 3, 'Gravity enters the power statement and nothing else, so head and efficiency read the same on both fluids and give no hint that the wrong one was used.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 9, 'Brake power per stage on a 0.90 gravity fluid reads 0.1984706437 hp at 40 Hz and 0.9579193256 hp at 70 Hz for one duty. Why is the spread so wide?', '["Efficiency falls steeply with speed and divides the power statement.", "The gravity of 0.90 is applied in the head and again in the power.", "Power carries the cube of the speed ratio, and a duty rate held fixed also moves the point that is read on the reference curve.", "The stage passes more fluid than the duty rate states."]'::jsonb, 2, 'The intermediate readings are 0.3836902045 hp at 50 Hz and 0.6286657970 hp at 60 Hz, so nothing in the sweep steps or turns over.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 10, 'Of head, efficiency and brake power at one duty, which is not an independent reading?', '["Brake power, because it is assembled from the other two along with rate and gravity, so it carries every error either of them carries.", "Efficiency, because the region word is graded against the scanned best efficiency rate, so the same fit feeds both the reading and the grading that is reported beside it.", "Head, because the affinity mapping scales it by the square of the speed ratio while the other two readings are handed back at the reference speed untouched.", "None of the three, each coming off its own fit."]'::jsonb, 0, 'An error in a head point moves head and power together, an error in an efficiency point moves efficiency and power together, and nothing moves power alone.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 11, 'A batch of duties is filtered on the region word, and a run at 40 Hz and 2500 bbl/d survives as upthrust. What has the filter let through?', '["A reading taken below the reference frequency, so the affinity mapping has scaled the head down by the square of a ratio that the region word itself never sees at all.", "A reading whose head has already gone negative.", "A reading the engine had refused and returned empty.", "A reading flagged outside the published data, returning 7.1087301587 ft and 0.1984706437 hp."]'::jsonb, 3, 'It looks exactly like the 3500 bbl/d row that is legitimately inside the data, because region says where a duty sits against the pump''s sweet spot and nothing else.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 12, 'Which of the fields returned at one duty tells you that the reading should not be used?', '["The region word, which reports invalid whenever the duty has left the interval the vendor was prepared to publish measurements across.", "None of them.", "The brake power, which is returned as NaN as soon as any of the inputs behind it falls outside the range the fit was built on.", "The range flag, which is the field the package intends a reader to treat as a gate on everything reported beside it."]'::jsonb, 1, 'Every one of the fields is returned with the same confidence and the same precision at every input, so the call refuses to grade itself.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 13, 'One stage of the published curve makes 27.914286 ft at 2500 bbl/d and 60 Hz. What does that reading know about the design around it?', '["Nothing at all: not the head the well requires, not how many stages are needed to make it, and not what the motor is rated for.", "The stage count, since head required divides by it.", "The motor rating, through the brake power per stage.", "The head required, through the region word."]'::jsonb, 0, 'Those are three further translations beyond the stage, and each of them has its own way of going wrong.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 14, 'A duty comes back recommended, inside the published data, and off a fit whose residual sits well under its threshold. What has that cleared?', '["The transcription, the region and the range, which between them are the three checks this module runs before it will return a reading it is prepared to stand behind.", "Everything the stage reading is asked to establish.", "Very little, since all three can be true of a curve typed in wrong and a fluid the curve does not apply to.", "The fluid, since the residual is measured on it."]'::jsonb, 2, 'A teaching curve with 28.0 ft typed as 26.0 has a residual of 0.58797473 ft against a threshold of 0.640000 ft, raises nothing, and reads 26.942857 ft at 2500 bbl/d.'),
  ('esp', 'beginner', 'module', 'm04-the-duty-point', 15, 'Read at 60 Hz from 1500 to 3500 bbl/d, the region word goes downthrust, then recommended, then upthrust, while every row stays inside the published data. What does that show?', '["That the published interval is narrower than the recommended band, so the vendor measured only part of the span the engine is prepared to call recommended on this curve.", "That the region word is graded against the ends of the published interval once the duty rate has been mapped back to the reference speed.", "That the best efficiency rate lies outside the data.", "That region and range are two separate judgements made on one reading."]'::jsonb, 3, 'Region grades a duty against the scanned best efficiency rate at 0.75 and 1.25 of it, which is a question about the pump rather than about where the numbers came from.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 1, 'The published golden set carries its own row at 40 Hz and 3200 bbl/d. What did the engine return for it?', '["A head of NaN and a region of invalid, because the equivalent rate on the reference curve falls beyond the last rate the vendor was prepared to publish a measurement at.", "0.052063492056 ft of head and 0.004290703685 hp, printed to twelve figures with the range flag false.", "A refusal, with no head fit and a message.", "18.98571429 ft, clamped at the published high."]'::jsonb, 1, 'That head is 0.00234792 of what the same curve gives at that rate at 60 Hz, and nothing in the shape of the answer says so.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 2, 'What is the equivalent rate on the reference curve for a duty of 3200 bbl/d taken at 40 Hz, and how far outside the data does it fall?', '["2742.857143 bbl/d, comfortably inside the data.", "3200 bbl/d, the rate never being remapped.", "4125.6000 bbl/d, some 625.6000 bbl/d outside.", "4800.0000 bbl/d, which is 1300.0000 bbl/d beyond the published range high of 3500 bbl/d."]'::jsonb, 3, 'Rate scales with speed, so a slower drive is read at a higher rate on the reference curve, which is why slowing down can walk a design out of its own data.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 3, 'What does an actual refusal look like in this fitting path?', '["A curve handed two points returns ok false, no head fit at all, and a message that three points are needed.", "A reading whose range flag comes back false, since the engine has then declared that the number it produced came from outside the data the vendor measured.", "A warning list carrying the outsideCurve code, which is the way this package declines to stand behind a stage reading it had to extrapolate to reach.", "A brake power handed back as a negative horsepower."]'::jsonb, 0, 'The other stopper is a drive frequency of zero, which returns a head of NaN and a region of invalid rather than a number.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 4, 'Reading the published curve at 3400, 3500 and 3600 bbl/d gives 20.09714286, 18.98571429 and 17.82571429 ft. What changes at the boundary between those rows?', '["The head step widens sharply.", "The region word turns to upthrust.", "The boolean alone, because the head steps are the same size on either side of it and no other field records that a boundary was crossed.", "The horsepower turns over and falls."]'::jsonb, 2, 'Nothing snaps anywhere in the sequence, and smooth degradation is exactly what makes an extrapolated reading so hard to see.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 5, 'What does the range flag tell a reader about how far outside the published data a reading sits?', '["It reads false more emphatically as the equivalent rate climbs, so a reading far past the data can be told apart from one that has only just left it.", "Nothing, because it carries no distance.", "It is returned alongside a distance in bbl/d past the range high, which is the quantity the reader is expected to judge the reading against.", "It turns false only once the head fit has passed its zero crossing, so any false flag means the reading was already unusable."]'::jsonb, 1, 'It reads identically 100 bbl/d past the data and 1300.0000 bbl/d past it, and the distance is what decides whether a reading is worth anything.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 6, 'A reference stage model fits a quadratic to points generated from a quadratic shape, recovering them to machine precision. How does it behave past its published data?', '["Identically, falling smoothly from 18.59200000 ft at 3500 bbl/d to 3.16288000 ft at 4700 bbl/d.", "It holds its last measured value, because an exact fit has no residual left with which to drift away from the points it was built on and so cannot extrapolate wrongly.", "It diverges much faster, having no cubic term.", "It refuses, its published range being enforced."]'::jsonb, 0, 'The behaviour belongs to extrapolation rather than to the polynomial degree or the residual, so a perfect fit extrapolates as confidently as an imperfect one.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 7, 'The head at 3600 bbl/d is very nearly right and the head at 4800 bbl/d is worthless. What do those two readings share?', '["A region word of recommended, since both rates fall inside the band that the scanned best efficiency rate defines around itself on this curve.", "A warning coded outsideCurve, which the stage reading raises at any rate past the published high whatever the distance beyond it turns out to be.", "A brake power returned as NaN.", "The same code path, the same output format and the same range flag."]'::jsonb, 3, 'One is 100 bbl/d past the data and the other 1300.0000 bbl/d past it, and none of the five returned fields separates them.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 8, 'Where does the cubic head fit on the published curve finally cross zero?', '["At 4800.0000 bbl/d, where the golden row sits.", "At 5434.80 bbl/d, with the efficiency fit.", "At 4806.6229 bbl/d, a full 1306.6229 bbl/d beyond the last rate the vendor measured.", "At 4909.9025 bbl/d, as the 540 series does."]'::jsonb, 2, 'Every rate between the range high and that crossing returns a positive, plausible number, so the sign change arrives far too late to serve as a guard.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 9, 'At 4900 bbl/d the efficiency is still positive at 0.21894857 fraction, yet the brake power is negative. Why?', '["The hydraulic power went negative with the head, and a positive efficiency divides it without changing its sign.", "The efficiency fit reaches zero at 5434.80 bbl/d and the sign of the power follows the slope of that fit rather than its value, so power turns before efficiency does.", "The rate has passed the divisor''s valid span.", "The pumped gravity enters as a negative correction."]'::jsonb, 0, 'On a curve shaped the other way round a negative efficiency would be a second route to the same sign, which is why power carries both other readings.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 10, 'Where is the only hard stop in the chain running from a stage reading to a stack?', '["The stage reading declines to hand back a negative head, so the sequence halts at the rate where the head fit crosses through zero on its way down.", "The stage count returns NaN on a head per stage of zero or less.", "The range flag turns false, which the sizing treats as a gate and so declines to size a stack against a reading taken outside the published data.", "The warning list raises the outsideCurve code, and no stack is returned once any coded condition has been met on the duty asked for."]'::jsonb, 1, 'By the time it fires the reading has been wrong for 1306.6229 bbl/d, so the one refusal in the chain arrives after every answer that mattered.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 11, 'On the gassyOffshore design the head per stage reaches zero at 33.6104 Hz. What does that say about the usable speed range?', '["That the design is safe down to just above that speed, since a positive head per stage is what the stage count divides by and the count stays finite the whole way down.", "That the drive should be held within the 26.3896 Hz band above it, which is the interval over which the affinity mapping keeps the equivalent rate inside the published data.", "That the stage count is undefined below 50 Hz.", "Very little, because the answers had stopped meaning anything many Hz above it."]'::jsonb, 3, 'On the recorded finding head did not go negative until 36.1016 Hz, some 6.5 Hz below the speed at which the sizing had already stopped meaning anything.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 12, 'Swept down to 40 Hz with its duty held, the gassyOffshore design returns 1009 stages against 192 at its design speed. What produced that multiple?', '["The head required rose with the equivalent rate of 4125.6000 bbl/d, because a slower drive must lift the same fluid against a larger friction component at the higher rate the curve is read at.", "The sizing added margin once the flag turned false.", "The head per stage fell by a factor of 5.2523, and the count is the head required divided by that and nothing else.", "The affinity law cubes the ratio inside the count."]'::jsonb, 2, 'The count multiple of 5.2552 and the head multiple of 5.2523 differ only by the rounding up to a whole stage.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 13, 'A recorded finding puts a design at 40 Hz, the lowest frequency the golden set tests. What did the sizing hand back?', '["926 stages off a stage making 3.9802 ft, some 5.58 times the design speed stack, with three warnings and no refusal.", "A refusal, once a third warning had been raised.", "The design speed stack, the frequency ignored.", "A stage count of NaN, the head having gone negative."]'::jsonb, 0, 'Nothing compares a count or a head per stage against its value at the design speed, so a stack five times too tall is returned in the same field as a correct one.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 14, 'The highWaterCut design, sized at 50 Hz, is taken down to 40 Hz and stays inside its published data throughout. What does that establish?', '["That a design sized at a lower frequency carries more margin, because the affinity mapping has less distance to travel before the reading reaches the end of the published range.", "That the range flag is compared against the design frequency rather than the reference one, so a design is only ever measured against the speed it was originally sized at.", "That slowing the drive does not put a design outside its data, and where the equivalent rate lands is what does.", "That its stage count is independent of frequency."]'::jsonb, 2, 'Its equivalent rate at 40 Hz is 6147.6000 bbl/d and its distance past the end of the data there is -3652.4000 bbl/d, while its count still runs from 264 stages to 445.'),
  ('esp', 'beginner', 'module', 'm05-outside-the-data', 15, 'Across the last four rows of the gassyOffshore sweep the stage count runs 481, 589, 748 and 1009. What does the warning count do?', '["It climbs by one at each row, so the count tracks the distance the equivalent rate has travelled past the end of the published data.", "It falls back to zero once the outsideCurve condition has been reported at the first row it was met on, the codes not being repeated afterwards.", "It rises to three at 1009 stages, which is the point at which the sizing begins to warn about the height of the stack itself.", "It stays at two throughout."]'::jsonb, 3, 'The same two codes, outsideCurve and upthrust, stand at 481 stages and at 1009, so the count saturates immediately and then says nothing more.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Four things establish a stage curve before any reading is taken from it. What are they?', '["Its points, its best efficiency rate, the recommended band around that rate, and the threshold against which the head fit residual is measured.", "Its points, its head fit degree, its normalising scale of 3500 bbl/d, and the divisor that turns a head reading into a horsepower.", "Its housing diameter and its rate at best efficiency.", "Its points, its published rate range, its reference frequency and its curve specific gravity."]'::jsonb, 3, 'The published golden curve is five points from 1500 to 3500 bbl/d at 60 Hz on a 1.0 gravity fluid, and every later step is read against those four facts.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Which step must come before head is read, and be taken by hand rather than left to the panel?', '["Checking the pumped gravity against the curve gravity.", "Mapping the duty rate back to the reference speed, because the frequency you set is never the rate the curve is read at.", "Reading the region word before the head behind it.", "Recording the housing diameter of the stage."]'::jsonb, 1, 'At 50 Hz a duty of 2500 bbl/d is 3000.000000 bbl/d on the reference curve, and reading the published curve at the duty rate instead is this tier''s most expensive single mistake.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Why measure the distance past the published high yourself instead of accepting what the flag reports?', '["The flag says false and stops there, while the distance is what decides whether the reading is worth anything.", "The flag is computed against the duty rate rather than the equivalent rate, so a reading taken well outside the data on the reference curve can still come back with the flag standing at true.", "The flag is only set once a warning has been raised.", "The flag is unavailable below the reference frequency."]'::jsonb, 0, 'The published high is 3500 bbl/d, so an equivalent rate of 4800.0000 bbl/d sits 1300.0000 bbl/d outside it and the flag reports that in one bit.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Why is brake power per stage read last and trusted least?', '["It is the only reading that moves with the pumped specific gravity, so it is the most sensitive to an input the vendor curve itself never carried.", "It is scanned on a grid rather than evaluated, so it inherits the quantisation the best efficiency rate does and cannot be resolved any more finely.", "It carries the errors of both other readings.", "It is evaluated on a separate cubic of its own, fitted to vendor power points that are published far less carefully than head and efficiency."]'::jsonb, 2, 'It is assembled from head, efficiency, rate and gravity through 135635.80083124, and nothing anywhere in the reading moves the power alone.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 5, 'What is a reader expected to be able to do at the end of the Associate tier?', '["Size a stack against a well.", "Pick a motor and a cable.", "Correct a curve for viscosity.", "Read one stage and say where its answers stop meaning anything."]'::jsonb, 3, 'The tier owns the stage and nothing beyond it, so the reading and the judgement about the reading are the whole of what it delivers.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 6, 'Why is a stage worked in a fixed order rather than in whatever order the panel returns its fields?', '["Because each step is a check on the step before it, so skipping one hides the failure of the others.", "Because the engine evaluates the head fit, the efficiency fit and the power statement in that sequence internally, and a reader who departs from it quotes fields computed against different inputs.", "Because the region word and the range flag are populated only once the best efficiency scan has completed, so any reading taken before that step returns both of them empty.", "Because the panel caches its last duty."]'::jsonb, 0, 'Establishing the curve, checking the residual against its threshold, scanning for the best efficiency point, mapping the rate back and measuring the distance past the data all come before the three readings for that reason.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 7, 'A well is to pass 3000 bbl/d. Which catalogue reference stage does the published rate range point to, and on what grounds?', '["ref-562-4000, because its rate at best efficiency of 4000 bbl/d leaves the duty comfortably below the peak, and a stage run below its best efficiency rate is the conservative selection to make.", "ref-540-2500, whose published range of 1250 to 3500 bbl/d contains the duty, rather than a stage picked on head.", "ref-400-1000, since head per stage is tallest there.", "ref-675-7000, whose peak efficiency of 0.74 is the highest."]'::jsonb, 1, 'A wider housing passes more rate and makes less head for it, so head is bought by stacking the stage the range chose rather than by reaching for a different one.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 8, 'What is a NaN doing when one of these calls returns it?', '["It is the engine declining to answer.", "It marks a reading taken outside the data.", "It is arithmetic falling over rather than a decision, and it propagates with no message attached to it.", "It is a warning code in numeric form."]'::jsonb, 2, 'Part of an answer can look perfectly healthy beside one, which is why a NaN is never protection and never a substitute for a check of your own.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Why does the shipped cable table carry copper resistance and no ampacity column?', '["Because ampacity is derived from the resistance already tabulated together with the conductor length, so a separate column would only repeat what the table holds.", "Because the selection runs on voltage drop alone, and the ampacity column was removed once the drop limit was found to bind first in every shipped case.", "Because the resistances are quoted at 77 degF, and an ampacity stated at that temperature would be unsafe to apply at the well temperatures these strings run at.", "Ampacity is an input rather than a property of copper."]'::jsonb, 3, 'It belongs to the insulation system and the well temperature, which is why the ampacity check in the selection currently passes by construction.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 10, 'A design at 40 Hz returns 445 stages against 264 at its design speed and raises no warning at all. What does that silence mean?', '["Only that no coded condition was met, which is not the same as a design that was checked and passed.", "That the sizing compared the stack against the one at the design speed and found the growth acceptable, which is exactly the clearance a zero warning count is written to express.", "That the stack is within one stage of its requirement.", "That warnings are suppressed below the design speed."]'::jsonb, 0, 'The quietest rows in that sweep are the ones furthest from the design, and the warning list carries no order and no magnitude anywhere in it.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which set of units does this tier report a stage in?', '["bbl/d, ft of head, hp and Hz, with pressures in psig, because a gauge reading is what an operator reads at the wellhead and the module reports what can be observed.", "Cubic metres per day, metres of head and kilowatts, since the electrical half of an ESP design is metric and one system across the chain avoids a conversion at every seam.", "bbl/d, ft of head, hp and Hz, with pressures in psia.", "Whatever the vendor sheet was drawn in."]'::jsonb, 2, 'Mixed units sit among the traps of this tier because every seam in an ESP design is a place where one set can be swapped for another without comment.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What does one stage of the published curve return at 2500 bbl/d and 60 Hz on a fluid of specific gravity 1.00?', '["28.0000 ft, 74.00 percent and 0.62866580 hp.", "27.914286 ft of head, 0.73657143 fraction of efficiency and 0.69851755 hp of brake power.", "26.992525 ft, 0.739054805 fraction and 0.75437842 hp.", "27.914286 ft, 0.73657143 fraction and 0.62866580 hp."]'::jsonb, 1, 'The same duty on a 0.90 gravity fluid returns that same head and that same efficiency, and 0.62866580 hp.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Why does a stage reading taken outside the published data matter to the equipment at surface?', '["Every later step is built on it, so it arrives at the surface as an amperage.", "Because the range flag is carried forward through the sizing and the selection, so a design flagged at the stage is flagged again at every step that consumes it.", "Because the surface numbers are computed from the published curve directly rather than from the stage reading, so the two diverge once the duty leaves the data.", "Because the drive reads the stage curve to set its own output frequency, so a reading outside the data moves the speed the design was sized at."]'::jsonb, 0, 'A stack count divides by the head per stage, a motor is sized from the power that follows, and a cable from the current after that.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Which questions does this tier leave entirely unanswered?', '["How the head fit is built, how the best efficiency point is scanned for and how the region word is graded, each deferred to the tier that first puts it to work in a design.", "What one stage makes, and on which fluid.", "How many stages, what the well requires of them, and what the motor draws to turn them.", "Where the fit stops describing the pump."]'::jsonb, 2, 'There is no intake, no gas, no cable and no clock anywhere in it, and each of those three questions is a further translation with its own way of going wrong.'),
  ('esp', 'beginner', 'module', 'm06-the-associate-reading', 15, 'The package carries two conversions for one gradient, the rounded 0.433000 psi/ft per specific gravity and the exact 0.433333333333. How was the disagreement settled?', '["The rounded field form was replaced with the exact one throughout, a fixed 0.076982 percent bias on every head in the package being a numeric defect rather than a matter of convention.", "It was recorded for a human decision, because different consumers use different conversions and choosing between them moves a number somebody is looking at in a live application today.", "Both were kept and their mean is used.", "It was adjudicated a convention, and the practice that keeps the two exact is to derive the specific gravity from the design gradient."]'::jsonb, 3, 'The gap is a fixed 0.076982 percent of whatever head it sits on, worth 3.832442 ft on the gassyOffshore design.'),
  ('esp', 'beginner', 'final', null, 1, 'Someone proposes ref-540-2500 for a well that must pass 5000 bbl/d, arguing that enough stages on the shaft will carry the extra rate. What is wrong with that argument?', '["Nothing is wrong, provided the motor is uprated to suit.", "The argument holds only at the reference frequency of 60 Hz.", "Stacking buys head and never rate, so the rate a pump passes is set by the stage itself, and a duty of 5000 bbl/d belongs on ref-562-4000 whose published range runs 2200 to 5600 bbl/d.", "It is sound on head but wrong on the housing outside diameter of 5.13 in."]'::jsonb, 2, 'The four reference stages trade the same way, a wider housing passing more rate and making less head for it, 28 ft at best efficiency on the 5.13 in stage against 23 ft on the 5.62 in one.'),
  ('esp', 'beginner', 'final', null, 2, 'A design note records that ref-675-7000 was read at 3000 bbl/d, that the call returned a head, and that the stage was judged suitable on that evidence. What has the note missed?', '["Its published range runs 4000 to 9800 bbl/d, so 3000 bbl/d sits below the data and the head came off a fit rather than off a measurement.", "The stage would have been suitable had the reading been taken at the reference frequency of 60 Hz, because below that speed the affinity mapping lifts the equivalent rate above the low end of the range.", "Nothing was missed, since a returned head is the engine confirming that the duty lies inside the rate band the vendor was prepared to publish for that housing.", "The note should have quoted the head at best efficiency instead."]'::jsonb, 0, 'Below the low end the region word comes back downthrust from the range rule alone, with the best efficiency point never consulted.'),
  ('esp', 'beginner', 'final', null, 3, 'A vendor sends a curve sheet measured at 50 Hz and asks which of the stored curves for that stage it should replace. What is the answer?', '["The 50 Hz entry for that stage, which the catalogue keeps beside the 60 Hz one so that a drive running below the reference speed does not have to be mapped through the affinity laws at all.", "The efficiency fit only, head being independent of speed.", "Both fits, since a fresh sheet replaces the whole stage record.", "None of them, because the engine holds one curve at a reference frequency of 60 Hz and reaches every other speed through the affinity laws rather than through a second curve."]'::jsonb, 3, 'There is no impeller in the model either, so trim and wear sit outside it entirely and every stage in a stack is the same stage.'),
  ('esp', 'beginner', 'final', null, 4, 'Two catalogue stages are weighed for one duty and the wider housing is rejected on the grounds that a wider stage must be the less efficient of the two. Is that sound?', '["Yes, because a wider housing passes more rate and every stage trades its efficiency away for the rate it is asked to carry.", "No, peak efficiency rises with housing size, from 0.63 fraction on the smallest stage to 0.74 on the largest.", "Yes, and the trade shows in the head at best efficiency, which falls from 33 ft on the smallest stage to 18 ft on the largest of the four.", "It depends on the drive speed, since the affinity laws move efficiency with frequency and a wider stage is usually turned more slowly than a narrow one."]'::jsonb, 1, 'Head at best efficiency runs the other way, 33 ft on ref-400-1000 down to 18 ft on ref-675-7000, so a wider stage buys rate with head and not with efficiency.'),
  ('esp', 'beginner', 'final', null, 5, 'A batch of stage readings is cleaned by discarding every row that came back NaN, and what is left is treated as sound. Why is the batch no safer for it?', '["Because NaN propagates without any message attached to it, so a row that survived the filter may still be carrying one that was produced further upstream in either of the two fits behind the reading.", "Because a NaN row can be recovered by lowering the drive frequency.", "NaN is arithmetic falling over rather than a check, and almost nothing in this path returns one, so every extrapolated reading survives the filter as a fully formed number.", "Because the discarded rows were the only ones inside the published range."]'::jsonb, 2, 'A zero drive frequency is one of the few calls that does stop, returning a head of NaN with the region invalid.'),
  ('esp', 'beginner', 'final', null, 6, 'A 20 cp fluid at 58 lbm/ft3 goes through the stage and the head handed back is identical to the water reading, while correction required comes back true. What has the module done?', '["It reported the kinematic viscosity as 21.517241 cSt, said a correction is needed, applied none, and returned the water curve unchanged with a note that it overstates head and efficiency.", "It applied the Hydraulic Institute factors from ANSI/HI 9.6.7 and reported the corrected head.", "It refused the reading and handed back a head of NaN.", "It corrected the efficiency but not the head, gravity entering the power statement alone."]'::jsonb, 0, 'An 8 cp fluid at the same density is 8.606897 cSt and passes the 10 cSt mark without a note at all.'),
  ('esp', 'beginner', 'final', null, 7, 'A reviewer asks for the cable ampacity check to be repaired so that it stops passing every size put in front of it. How was that finding adjudicated?', '["Fixed by adding an ampacity column to the shipped table, ampacity being a property of the copper cross section in the same way resistance is, and therefore something the table can carry.", "Confirmed as a fails-open and left as it is, because the shipped table carries copper resistance and no ampacity column by design, so the check does not currently check anything.", "Recorded for a human decision rather than changed, since the two candidate ampacity tables disagree and choosing between them would move a number that a live application is displaying today.", "Adjudicated correct, the check having always been sound."]'::jsonb, 1, 'Ampacity belongs to the insulation system and the well temperature, so it is an input to a cable selection rather than a property of copper.'),
  ('esp', 'beginner', 'final', null, 8, 'A stage curve passes its transcription check with a head fit residual comfortably under two percent of the tallest published point. What does that pass guarantee about a head then read from it at one rate?', '["That the head at that rate is within two percent of the value the vendor measured, which is what the threshold was scaled to protect.", "That the rate is inside the published range as well, the residual being computed over the points the vendor was prepared to publish.", "That the efficiency transcription passed at the same time, both fits being built from the same five rates inside one call.", "Only that the five typed head numbers sit close to a smooth cubic."]'::jsonb, 3, 'A teaching curve with 28.0 ft typed as 26.0 reaches 0.58797473 ft against a threshold of 0.640000 ft, raises nothing, and reads 26.942857 ft at 2500 bbl/d.'),
  ('esp', 'beginner', 'final', null, 9, 'Two engineers type the same vendor sheet and their curves return the same rmse. One set of residuals alternates in sign and is symmetric about the middle point, the other carries one large residual against four small ones. What now?', '["Accept both, since the two curves agree on the only number the check reports.", "Raise the fit degree on the second curve until its residuals turn symmetric too.", "Check the transcription of the point behind the large residual, because an rmse summed over five points averages one bad point away while the residual at each point is what exposes it.", "Reject both and ask the vendor for a longer list of points."]'::jsonb, 2, 'The well behaved pattern on the published curve runs -0.01428571, 0.05714286, -0.08571429, 0.05714286 and -0.01428571 ft.'),
  ('esp', 'beginner', 'final', null, 10, 'A report quotes the head fit coefficient of -29.7499999999 on the squared term as a head per squared bbl/d. By how much is that wrong?', '["By the square of the normalising scale, the fit being built in rate divided by 3500 bbl/d rather than in rate itself.", "By the square of the ratio of the reference frequency to the drive frequency, the coefficients being stored at 60 Hz while head carries with the square of the speed.", "Not at all, the coefficient being dimensionless as it stands.", "By a factor of 3500, the scale entering every term linearly."]'::jsonb, 0, 'Working in that variable keeps every column of the normal equations near one, which is why cubing raw rates in the thousands is avoided.'),
  ('esp', 'beginner', 'final', null, 11, 'Raising the degree of the head fit until it passes through all five published points is proposed, so that the residual disappears. What would that buy?', '["A fit that reproduces the vendor sheet exactly at the measured rates and interpolates smoothly between them, which is what the two percent threshold was written to reward.", "A curve that finally has a domain, since a fit passing through every published point cannot be evaluated at a rate outside the range those points span.", "Nothing, the degree being fixed at three by the catalogue.", "A curve with no residual that swings violently between the points, and the loss of the only transcription evidence available."]'::jsonb, 3, 'The residual is the price of a smooth curve, and an alternating symmetric pattern says that price is being paid evenly across the points.'),
  ('esp', 'beginner', 'final', null, 12, 'A summary table ranks stage curves by head fit rmse and puts a reference stage first on 0.00000000000018 ft, ahead of the vendor curve on 0.0534522484 ft. What is wrong with the ranking?', '["The two residuals are quoted in different units, one in feet of head and the other as a fraction of the tallest published point.", "A reference stage is a shape fitted to itself, so its residual is machine noise.", "The efficiency fit residual should have been used instead, brake power being derived from efficiency and carrying its error onward.", "The vendor curve should have been left out, five points being too few to support a cubic in the first place."]'::jsonb, 1, 'Only the vendor residual measures anything, because its points came from outside the arithmetic that fitted them.'),
  ('esp', 'beginner', 'final', null, 13, 'A spreadsheet evaluates the stored head fit at the duty rate and then multiplies by the square of the speed ratio. Where does it part company with the engine at 50 Hz?', '["The engine divides the duty rate by the ratio first and reads at 3000.000000 bbl/d, so the spreadsheet applies the law at the wrong place on the curve.", "Nowhere, the two orders being equivalent, though the spreadsheet loses a little precision by squaring a ratio the engine carries as an exact fraction of the reference frequency.", "It should have multiplied by the cube of the ratio and not the square.", "It reads efficiency correctly and head incorrectly."]'::jsonb, 0, 'A duty of 2500 bbl/d at 50 Hz makes 16.7063492063 ft, where the same duty at 60 Hz makes 27.9142857143 ft.'),
  ('esp', 'beginner', 'final', null, 14, 'Head points are loaded with no efficiency points, the fit returns ok true, and head reads at every rate. Which readings have gone, and where do they surface?', '["Nothing has gone, brake power being fitted from the vendor power points instead.", "The head fit is built but its residual is no longer reported.", "The best efficiency rate and the brake power per stage both come back NaN while head still reads 27.914286 ft at 2500 bbl/d, so the holes appear only in the fields that needed efficiency.", "The region word comes back invalid at every rate, the band around the peak being unavailable."]'::jsonb, 2, 'The call returns ok true with a warning that no efficiency points were given, which is a partial refusal rather than a stop.'),
  ('esp', 'beginner', 'final', null, 15, 'A duty is reported recommended. The band that produced the word runs at 0.75 and 1.25 of a best efficiency rate that was scanned on a 5.0000 bbl/d grid. What does the word assert?', '["That the duty sits at the peak of the efficiency curve to within the 5.0000 bbl/d spacing of the scan that located the best efficiency rate.", "That the reference rate sits inside a band whose edges carry the same quantisation, and that the duty is inside the published data.", "That the duty was compared against the vendor sheet rather than against a fitted curve, the recommended word being awarded only at measured rates.", "That the stage is drawing its least power, the recommended band being built around the rate at which the efficiency fit reaches its highest value."]'::jsonb, 1, 'Recommended is the one word only ever awarded inside the published range, so it carries a guarantee of provenance that the other two do not.'),
  ('esp', 'beginner', 'final', null, 16, 'A procurement note gives the best efficiency of the pump as 74.00 percent at 2500 bbl/d and names the engine as its source. What has the note confused?', '["The efficiency at the duty with the efficiency at the best efficiency rate, the two differing only because the drive was running below the reference frequency of 60 Hz when the sheet was read.", "The efficiency fit with the head fit, since the peak quoted belongs to the head curve and the two are fitted independently from the same five published rates.", "Percent with fraction, which is a unit slip and nothing more.", "A measured point on the sheet with the peak of a cubic fitted through five of them, which the engine puts at 0.739054805 fraction and 2635.0000 bbl/d."]'::jsonb, 3, 'The fit reads 0.73657143 fraction at the sheet best rate of 2500 bbl/d, below its own peak.'),
  ('esp', 'beginner', 'final', null, 17, 'To test a suspect transcription, a reviewer proposes checking whether the best efficiency rate moved. Why will that test pass whatever the head points say?', '["The scan reads the efficiency fit alone, so a head error leaves the rate at 2635.0000 bbl/d even in the decimal slip version, while the head reported there moves from 26.992525 to 26.041925 ft.", "Because the scan grid of 5.0000 bbl/d is too coarse to resolve a shift of that size.", "Because the best efficiency rate is read from the catalogue and not computed.", "Because the two fits are built together and share their residual."]'::jsonb, 0, 'There is no check on the efficiency transcription at all, the threshold being a head threshold against the tallest published head point.'),
  ('esp', 'beginner', 'final', null, 18, 'A batch is sorted into three piles by the region word alone and the upthrust pile is sent back for a wider stage. Which rows in that pile were never graded against the best efficiency point?', '["None of them, since the band around the best efficiency rate is applied first at every rate and the range check only qualifies the word afterwards with the boolean beside it.", "The rows below 0.75 of the best efficiency rate.", "Every row above the published high, because outside the data the range decides the word on its own and the peak is not consulted.", "Only the rows at a drive frequency of zero."]'::jsonb, 2, 'On ref-540-2500 the word reads upthrust at 3350 bbl/d from the band and upthrust again at 3800 bbl/d from the range, with the same string in both.'),
  ('esp', 'beginner', 'final', null, 19, 'Narrowing the published range on a curve is suggested so that the scan resolves its peak more finely. What would that actually change?', '["Nothing, since the scan takes 400 steps between the ends of the range and then refines the best of them until the derivative of the efficiency fit changes sign.", "The spacing, which is the range divided by 400, so a narrower range does give a finer grid whatever the shape of the curve on it.", "The peak value as well as the rate, the efficiency fit being rebuilt from whichever published points still fall inside the narrowed range.", "The head at the peak, but not the rate at which it is read."]'::jsonb, 1, 'The scan never looks outside the published range, so the rate it returns cannot lie outside the data whatever the fit does there.'),
  ('esp', 'beginner', 'final', null, 20, 'A specification sheet gives the head at the best efficiency point as the head the stage makes. What is the objection?', '["The head at the best efficiency point is a fitted value rather than a measured one, and the sheet should have quoted a published point.", "The head there is the tallest the stage makes, but only at the reference frequency of 60 Hz and on the curve fluid.", "Brake power is at its lowest there, so the head quoted belongs with a power that the motor will never be asked for.", "Head falls all the way across the range, so that reading is one of the lower ones."]'::jsonb, 3, 'The tallest head on the published curve is 31.985714 ft at 1500 bbl/d, against 26.992525 ft at the best efficiency rate.'),
  ('esp', 'beginner', 'final', null, 21, 'A motor is sized from the brake power at the best efficiency rate, on the reasoning that a stage at its best efficiency draws its least power. What has that sizing done?', '["Undersized the motor, because power climbs from 0.64381596 hp to 0.75437842 hp across the published range without turning over.", "Oversized the motor, since the power at the best efficiency rate is the highest the stage draws anywhere inside the range the vendor published for it.", "Sized it correctly, that rate carrying the largest power draw.", "Sized it on efficiency rather than on head, which is the same thing."]'::jsonb, 0, 'Rate rises faster than head and efficiency fall, so the product keeps growing and the highest draw sits at the top of the range.'),
  ('esp', 'beginner', 'final', null, 22, 'A stack is sized from a head per stage read at 60 Hz while the drive is to run at 50 Hz. Which way is the count wrong, and by what?', '["Long, by the square of the speed ratio, since head carries with the square of the speed and the stack was sized on the larger of the two readings available.", "Short, by the ratio of the two drive frequencies, the equivalent rate on the reference curve moving in proportion to the speed and head along with it.", "Short, in the ratio of 27.9142857143 ft to 16.70634921 ft, the count being the head required divided by the head per stage.", "Correct, the count being independent of the drive speed."]'::jsonb, 2, 'The error is multiplied by every stage in the stack before anyone sees it, which is why the mapping is done by hand first.'),
  ('esp', 'beginner', 'final', null, 23, 'Shaft work for a stack is computed with the peak efficiency because the duty sits close to the best efficiency rate. Which way does that error run?', '["It overstates the shaft work, the peak being the lowest efficiency on the curve.", "It cancels, since head and efficiency move together at a duty.", "It moves the head per stage and leaves the power alone.", "It understates the shaft work at every stage, because efficiency divides and the reading at 2500 bbl/d is 0.73657143 fraction against a peak of 0.739054805."]'::jsonb, 3, 'Brake power is assembled from head, efficiency, rate and the pumped gravity, so nothing else in the pack absorbs the slip.'),
  ('esp', 'beginner', 'final', null, 24, 'One published head point turns out to have been mistyped. Of the three readings at a duty, which move and which stay?', '["All three move, the three readings being taken from one fit through the five published points.", "Head and brake power move, efficiency does not.", "Efficiency and brake power move, head being read straight from the published points without a fit.", "Only head moves, brake power coming off its own fit through the vendor power points on the sheet."]'::jsonb, 1, 'Power carries every error the other two carry, and nothing moves power on its own.'),
  ('esp', 'beginner', 'final', null, 25, 'A field check recomputes brake power as rate times pressure rise over 58824 and lands slightly away from the engine. How large is the gap and where is it from?', '["0.0008242606 in relative terms, this package carrying an exact divisor of 58775.513694 once it is taken into pressure units.", "About a tenth of the number, the field form working on water while the engine applies the pumped specific gravity to the head before the division is taken.", "0.076982 percent, which is the distance between the rounded gradient of 0.433000 psi/ft per specific gravity and the exact form the package also carries.", "Nothing at all, the two divisors being the same number."]'::jsonb, 0, 'The head form of the same statement divides by 135635.80083124, the constant the golden records.'),
  ('esp', 'beginner', 'final', null, 26, 'Every field at a duty prints to the same number of figures whether the duty sits in the middle of the data or far beyond its end. What does that uniformity cost the reader?', '["It costs accuracy, the extra figures being noise past the end of the data.", "It costs nothing, since the region word changes at the boundary.", "Nothing in the shape or the precision of the answer separates a measured region from an extrapolated one, so the boolean beside them has to be read deliberately every time.", "It hides the drive frequency, which is not returned in the pack."]'::jsonb, 2, 'The golden row at 4800.0000 bbl/d prints 0.052063492056 ft to twelve figures like every other reading in the set.'),
  ('esp', 'beginner', 'final', null, 27, 'It is proposed to confirm the affinity mapping by reading efficiency at one duty at two drive speeds and checking that the two agree. Will they?', '["Yes, and any disagreement points to the head fit rather than the efficiency fit, head being the only reading the affinity laws scale after the reference rate has been found.", "No, because the equivalent rate moves with the speed, so the same duty is read at a different place on the reference curve each time.", "Yes, efficiency being unchanged by speed under the affinity laws.", "No, because efficiency scales with the cube of the speed."]'::jsonb, 1, 'At 50 Hz and 2500 bbl/d the efficiency is 0.7222857143 fraction, which is the 60 Hz value at 3000.000000 bbl/d.'),
  ('esp', 'beginner', 'final', null, 28, 'One fluid at 8 cp and another at 20 cp, both at 58 lbm/ft3, are read on the same stage. What comes back for each?', '["8.606897 cSt with the Hydraulic Institute factors applied, then 21.517241 cSt with the same factors applied twice over.", "Both are corrected, the 10 cSt mark being a reporting threshold rather than the point at which the module begins to act.", "The first is refused as too thin for the water curve, the second returned with head and efficiency both reduced by the published factors.", "8.606897 cSt and nothing further, then 21.517241 cSt with a note and no correction applied."]'::jsonb, 3, 'Supplied factors of 0.85 on head and 0.70 on efficiency take an uncorrected 28.00000000 ft and 0.7000000000 fraction to 23.80000000 ft and 0.4900000000.'),
  ('esp', 'beginner', 'final', null, 29, 'Across four rows of a sweep the warning list stays two codes long while the stage count runs from 481 to 1009. What can the list be read to say about how far the design has travelled?', '["That the design stopped degrading once the second code appeared.", "That two codes is the ceiling and a third would need a refusal.", "Nothing whatever, since the codes carry no order and no magnitude, so outsideCurve reads the same 87.4783 bbl/d past the end of the data as it does 625.6000 bbl/d past it.", "That the count saturated because the stage count itself is bounded."]'::jsonb, 2, 'The distance exists in the reading, as an equivalent rate against the published high, and never in the warning.'),
  ('esp', 'beginner', 'final', null, 30, 'A team wants a rule that a reading may be used while it is no more than a stated distance past the published high. Which part of the returned pack supplies that distance?', '["None of it, so the equivalent rate has to be compared against the published high by hand before the rule can be applied.", "The boolean, which reports the crossing and the size of it together, being false only once the equivalent rate has cleared the published high by a margin.", "The region word, which grades the reading against the band around the best efficiency rate and so measures how far past the useful part of the curve the duty sits.", "The warning count, one code being raised for each 100 bbl/d."]'::jsonb, 0, 'At 3600 bbl/d the reading is very nearly right and at 4800 bbl/d it is worthless, and the flag reads the same at both.'),
  ('esp', 'beginner', 'final', null, 31, 'It is argued that a drive can be slowed safely until the head per stage turns negative, the sign change marking the limit of usable answers. What does that argument leave running?', '["Nothing, provided the equivalent rate is watched at the same time, since the sign change and the end of the published data are reached at very nearly the same speed on any design.", "Only the rows where the efficiency has also gone negative.", "Nothing at all, the stage count refusing first.", "Six and a half Hz of answers that had already stopped meaning anything, head on that design not going negative until 36.1016 Hz."]'::jsonb, 3, 'On the published curve the head fit does not reach zero until 4806.6229 bbl/d, which is 1306.6229 bbl/d past the end of the data.'),
  ('esp', 'beginner', 'final', null, 32, 'With the duty held, a drive is taken down in frequency. Which number decides whether the readings leave the data, and against what is it compared?', '["The drive frequency, against the reference frequency of 60 Hz the curve was measured at.", "The equivalent rate, against the published range high.", "The head per stage, against the head at the best efficiency rate on the same curve.", "The stage count, against the count the design returned at the speed it was sized at."]'::jsonb, 1, 'One published design leaves its data between 50 and 46 Hz while another never leaves it down to 40 Hz, and the second was sized at the lower speed.'),
  ('esp', 'beginner', 'final', null, 33, 'One stage read past the end of the data is a small wrong number. What turns it into a large one by the time a stack is quoted?', '["The count is the head required divided by the head per stage, so a head smaller by 5.2523 returns a stack 5.2552 times the one at the design speed.", "The rounding up of the count to a whole stage, which adds head at every step of the sweep until the accumulated margin dominates the number that is finally quoted.", "The warning count, which multiplies with the number of codes raised.", "The gravity, which enters the count as it enters the power."]'::jsonb, 0, 'Nothing in the sizing compares a count or a head per stage against its value at the design speed.'),
  ('esp', 'beginner', 'final', null, 34, 'Relying on the stage count returning NaN as the guard against extrapolated readings is proposed. Why is that guard of so little use?', '["It fires at every rate outside the published range, so it would stop useful work.", "It cannot fire at all, the count being an integer by construction.", "It fires only on a head per stage of zero or below, which on the published curve is reached 1306.6229 bbl/d after the readings stopped being worth anything.", "It fires on the warning count rather than on the head per stage."]'::jsonb, 2, 'That NaN is the only hard stop in the chain running from a stage reading to a stack.'),
  ('esp', 'beginner', 'final', null, 35, 'A report offers the published golden set as evidence that the engine declines to answer outside the data. Which row of that same set overturns the claim?', '["The row at a drive frequency of zero, which returns a head of NaN and a region of invalid, and is the only place in the set where the reading declares that it failed.", "The row at 40 Hz and 3200 bbl/d, which maps to 4800.0000 bbl/d and returns 0.052063492056 ft and 0.004290703685 hp.", "The row at 3500 bbl/d and 60 Hz, where the region word turns upthrust while inside the published range is still true and the head is 18.98571429 ft.", "No row does, the claim being correct as it stands."]'::jsonb, 1, 'That head is 0.00234792 of what the same curve gives at that rate at 60 Hz, and it is flagged and answered rather than refused.'),
  ('esp', 'beginner', 'final', null, 36, 'A duty is worked through but the best efficiency point is established only after the region words have been read and acted on. What has that ordering broken?', '["The head reading, which is scaled from the best efficiency head before the fit is evaluated at the duty.", "The transcription check, whose threshold is two percent of the head at the best efficiency point.", "The brake power, since efficiency at the duty is read as a fraction of the peak the scan returns.", "The words themselves, each being graded at 0.75 and 1.25 of that rate."]'::jsonb, 3, 'Region is the one field in the pack that depends on a number computed earlier in the reading rather than on the duty alone.'),
  ('esp', 'beginner', 'final', null, 37, 'A handover pack lists head, efficiency and brake power at a duty and nothing else. What must a reader be given before any of the three can be interpreted?', '["The stage count and the motor nameplate the readings will be carried into.", "The residual and the warning count, which settle the transcription.", "The points behind the curve, the published rate range, the reference frequency and the curve specific gravity, which are the four things that establish a stage at all.", "The drive frequency alone, everything else following from the affinity laws."]'::jsonb, 2, 'Below three points there is no curve to interpret at all, the fit returning ok false with no head fit.'),
  ('esp', 'beginner', 'final', null, 38, 'It is proposed to replace the rounded 0.433000 psi/ft per specific gravity with the exact 62.4 over 144 so that the package stops disagreeing with itself. How was that settled?', '["Adjudicated a convention rather than a defect, the fix being to derive the specific gravity from the design gradient, which is what the goldens and the consumers already do.", "Fixed in the engine, the two conversions being 0.076982 percent apart and the rounded one having been shown to move a published head by more than three feet on one of the designs.", "Confirmed as a fails-open, the conversion never being reached.", "Recorded for a human decision, with nothing changed either way."]'::jsonb, 0, 'The gap is worth 3.832442 ft of head on the gassyOffshore design and a fixed 0.076982 percent of whatever head it sits on.'),
  ('esp', 'beginner', 'final', null, 39, 'Handed one duty reading, a colleague asks the associate reader how many stages the well needs. What is the honest reply?', '["That the count follows from the head per stage and the head at the best efficiency point, both of which are already in the pack that was handed over.", "That the reading knows nothing of the head the well requires, which is a question the next tier answers.", "That the count can be given once the drive frequency is fixed, the stage reading carrying everything else the sizing needs on the fluid it was read for.", "That the count is the head per stage times the gravity."]'::jsonb, 1, 'There is no intake, no gas, no cable and no clock anywhere in the stage reading.'),
  ('esp', 'beginner', 'final', null, 40, 'A design needs 191.92829740 stages and is built with 192. What does the extra fraction of a stage do to the head?', '["Nothing, the count being rounded to the nearest whole stage either way.", "It removes 1.85986141 ft, the count having been rounded down.", "It leaves the head alone and moves only the brake power.", "The stack makes 4980.20162863 ft against a requirement of 4978.341767 ft, a margin of 1.85986141 ft which is bounded by one stage and never by a percentage."]'::jsonb, 3, 'Because stages are integers and the count rounds up, a stack always makes more head than it was asked for.'),
  ('esp', 'beginner', 'final', null, 41, 'Head per stage becomes head required, which becomes shaft horsepower, which becomes amps at the surface. What property of that chain makes an early error dangerous?', '["Each translation consumes the number before it without re-deriving it, so an error at one is invisible at the next and arrives at the surface as an amperage.", "Each translation multiplies the error by the number of stages in the stack, so a slip of a hundredth of a foot per stage becomes several feet of head before the motor is chosen.", "The chain is reversible, so the error can be recovered later.", "Every step raises a warning, which the next step clears."]'::jsonb, 0, 'That is why a stage read outside the published data reaches the surface as a current rather than as a head.'),
  ('esp', 'beginner', 'final', null, 42, 'A slide names ref-540-2500 as the pump selected for a well and prints its head at best efficiency as the pump rating. How many errors is that?', '["One, the stage being real but its rating quoted at the wrong rate on the curve.", "One, the head at best efficiency being a rating while the stage name is a shorthand.", "Two, one of provenance and one of reading.", "None, provided the drive is to run at the reference frequency of 60 Hz."]'::jsonb, 2, 'A reference stage is a shape with four named parameters and no part number behind it, and the head at best efficiency is a reading at that rate rather than an optimum.');
